package com.franco.desco.adapter.out.sqlserver.delivery;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.delivery.*;import com.franco.desco.application.delivery.port.out.DeliveryPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.delivery.DeliveryModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class DeliverySqlServerAdapter implements DeliveryPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,create,update,confirm,annul;public DeliverySqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("comercial","PA_EntregaSocio_Sel_Listado","items");get=f.callWithResultSets("comercial","PA_EntregaSocio_Sel_DetalleCompleto","header","details","incidents","files");create=f.call("comercial","PA_EntregaSocio_Ins_Registro");update=f.call("comercial","PA_EntregaSocio_Upd_RegistroPreliminar");confirm=f.call("comercial","PA_EntregaSocio_Upd_Confirmar");annul=f.call("comercial","PA_EntregaSocio_Upd_Anular");}
 public PersistenceResult<PageResult<DeliveryModels.Summary>>list(DeliveryCommands.ListDeliveries c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var out=e.executeJson(list,pf.forQuery(i,m,map("filtros",map("operativoVentaId",f==null?null:f.operativoVentaId(),"socioId",f==null?null:f.socioId(),"estadoProceso",f==null?null:f.estadoProceso(),"estadoControlCalidad",f==null?null:f.estadoControlCalidad(),"fechaDesde",f==null?null:f.fechaDesde(),"fechaHasta",f==null?null:f.fechaHasta()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio()))));return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar las entregas.");}
 public PersistenceResult<DeliveryModels.Detail>get(DeliveryCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("entrega",Map.of("entregaSocioId",c.entregaSocioId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la entrega."));var h=one(out,"header");if(h==null)return PersistenceResult.error("La entrega seleccionada no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Entrega consultada correctamente."),new DeliveryModels.Detail(header(h),rows(out,"details").stream().map(this::line).toList(),rows(out,"incidents").stream().map(this::incident).toList(),rows(out,"files").stream().map(this::file).toList()));}
 public PersistenceResult<Long>create(DeliveryCommands.Create c,SessionIdentity i,RequestMetadata m){var payload=map("entrega",map("operativoSocioId",c.operativoSocioId(),"predioId",c.predioId(),"codigoLote",c.codigoLote(),"fechaHora",c.fechaHora(),"pesoBrutoKg",c.pesoBrutoKg(),"taraKg",c.taraKg(),"pesoRechazadoKg",c.pesoRechazadoKg(),"estadoControlCalidad",c.estadoControlCalidad(),"ticketBalanza",c.ticketBalanza(),"observacion",c.observacion()),"detalles",lines(c.detalles()));var out=e.executeJson(create,pf.forWrite(i,m,c,payload));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nEntregaSocioId"),"No se pudo registrar la entrega.");}
 public PersistenceResult<Void>updatePreliminary(DeliveryCommands.UpdatePreliminary c,SessionIdentity i,RequestMetadata m){var payload=map("entrega",map("entregaSocioId",c.entregaSocioId(),"pesoBrutoKg",c.pesoBrutoKg(),"taraKg",c.taraKg(),"pesoRechazadoKg",c.pesoRechazadoKg(),"estadoControlCalidad",c.estadoControlCalidad(),"ticketBalanza",c.ticketBalanza(),"observacion",c.observacion()),"detalles",lines(c.detalles()));return PaAdapterSupport.result(e.executeJson(update,pf.forWrite(i,m,c,payload)),null,"No se pudo actualizar la entrega preliminar.");}public PersistenceResult<Void>confirm(DeliveryCommands.Confirm c,SessionIdentity i,RequestMetadata m){return PaAdapterSupport.result(e.executeJson(confirm,pf.forWrite(i,m,c,Map.of("entrega",Map.of("entregaSocioId",c.entregaSocioId())))),null,"No se pudo confirmar la entrega.");}public PersistenceResult<Void>annul(DeliveryCommands.Annul c,SessionIdentity i,RequestMetadata m){return PaAdapterSupport.result(e.executeJson(annul,pf.forWrite(i,m,c,Map.of("entrega",map("entregaSocioId",c.entregaSocioId(),"motivo",c.motivo())))),null,"No se pudo anular la entrega.");}
 private List<Map<String,Object>>lines(List<DeliveryCommands.Line>x){return x==null?List.of():x.stream().map(v->map("variedadPaltaId",v.variedadPaltaId(),"condicionComercialId",v.condicionComercialId(),"kilogramos",v.kilogramos())).toList();}private DeliveryModels.Summary summary(Map<String,Object>r){return new DeliveryModels.Summary(SqlValues.longValue(r,"entregaSocioId"),SqlValues.string(r,"codigoLote"),SqlValues.instant(r,"fechaHora"),SqlValues.decimal(r,"pesoBrutoKg"),SqlValues.decimal(r,"taraKg"),SqlValues.decimal(r,"pesoRechazadoKg"),SqlValues.decimal(r,"pesoAceptadoKg"),SqlValues.string(r,"estadoControlCalidad"),SqlValues.string(r,"estadoProceso"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"operativo"),SqlValues.longValue(r,"socioId"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"socioNombre"),SqlValues.decimal(r,"valorizacion"));}private DeliveryModels.Header header(Map<String,Object>r){return new DeliveryModels.Header(SqlValues.longValue(r,"entregaSocioId"),SqlValues.string(r,"codigoLote"),SqlValues.instant(r,"fechaHora"),SqlValues.decimal(r,"pesoBrutoKg"),SqlValues.decimal(r,"taraKg"),SqlValues.decimal(r,"pesoNetoKg"),SqlValues.decimal(r,"pesoRechazadoKg"),SqlValues.decimal(r,"pesoAceptadoKg"),SqlValues.string(r,"estadoControlCalidad"),SqlValues.string(r,"ticketBalanza"),SqlValues.string(r,"observacion"),SqlValues.string(r,"estadoProceso"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"predioCodigo"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"operativo"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"socioNombre"));}private DeliveryModels.DetailLine line(Map<String,Object>r){return new DeliveryModels.DetailLine(SqlValues.longValue(r,"entregaDetalleId"),SqlValues.intValue(r,"variedadPaltaId"),SqlValues.string(r,"variedad"),SqlValues.longValue(r,"condicionComercialId"),SqlValues.string(r,"condicion"),SqlValues.longValue(r,"precioComercialId"),SqlValues.decimal(r,"kilogramos"),SqlValues.decimal(r,"precioBase"),SqlValues.decimal(r,"precioAplicado"),SqlValues.decimal(r,"importe"));}private DeliveryModels.Incident incident(Map<String,Object>r){return new DeliveryModels.Incident(SqlValues.longValue(r,"incidenciaId"),SqlValues.string(r,"tipoIncidencia"),SqlValues.string(r,"severidad"),SqlValues.decimal(r,"pesoAfectadoKg"),SqlValues.string(r,"descripcion"),SqlValues.string(r,"estadoIncidencia"));}private DeliveryModels.File file(Map<String,Object>r){return new DeliveryModels.File(SqlValues.longValue(r,"archivoId"),SqlValues.string(r,"nombreOriginal"),SqlValues.string(r,"mimeType"),SqlValues.string(r,"secureUrl"),SqlValues.string(r,"categoria"),SqlValues.string(r,"descripcion"),SqlValues.instant(r,"fechaCarga"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
